changeSet.sql:
ALTER TABLE "${schema}".payroll_compliance_setting
 DROP CONSTRAINT ck_payslip_employee_fields;
ALTER TABLE "${schema}".payroll_compliance_setting
 ADD CONSTRAINT ck_payslip_employee_fields CHECK (
  jsonb_typeof(payslip_employee_fields) = 'array' AND
  payslip_employee_fields <@ '["EMPLOYEE_NAME","EMPLOYEE_CODE","DEPARTMENT","DESIGNATION","JOINING_DATE","GENDER","MARITAL_STATUS","UAN","ESIC","PAYSLIP_STATUS","GENERATED_DATE"]'::jsonb);

rollback.sql:
ALTER TABLE "${schema}".payroll_compliance_setting
 DROP CONSTRAINT ck_payslip_employee_fields;
UPDATE "${schema}".payroll_compliance_setting
 SET payslip_employee_fields = payslip_employee_fields - 'PAYSLIP_STATUS' - 'GENERATED_DATE'
 WHERE payslip_employee_fields ?| ARRAY['PAYSLIP_STATUS', 'GENERATED_DATE'];
ALTER TABLE "${schema}".payroll_compliance_setting
 ADD CONSTRAINT ck_payslip_employee_fields CHECK (
  jsonb_typeof(payslip_employee_fields) = 'array' AND
  payslip_employee_fields <@ '["EMPLOYEE_NAME","EMPLOYEE_CODE","DEPARTMENT","DESIGNATION","JOINING_DATE","GENDER","MARITAL_STATUS","UAN","ESIC"]'::jsonb);
